for(const reciter of RECITERS){const portraits={"ar.alafasy":"assets/reciters/alafasy.webp","ar.tariqmuhammad":"assets/reciters/tariqmuhammad.jpg","ar.abdurrahmanalsudais":"assets/reciters/abdurrahmanalsudais.jpg","ar.abdullahaljuhany":"assets/reciters/abdullahaljuhany.jpg","ar.salahalbudair":"assets/reciters/salahalbudair.jpg","ar.abdulbarialthubaity":"assets/reciters/abdulbarialthubaity.jpg","ar.abdulmuhsinalqasim":"assets/reciters/abdulmuhsinalqasim.jpg","ar.abdullahalbuayjan":"assets/reciters/abdullahalbuayjan.jpg","ar.ahmadalhuthaifi":"assets/reciters/ahmadalhuthaifi.jpg","ar.khalidalmuhanna":"assets/reciters/khalidalmuhanna.jpg","ar.alialhuthaifi":"assets/reciters/alialhuthaifi.jpg","ar.badralturki":"assets/reciters/badralturki.jpg","ar.husary":"assets/reciters/husary-original.png","ar.yasseraldossari":"assets/reciters/yasseraldossari.jpg","ar.muhammadalluhaidan":"assets/reciters/muhammadalluhaidan.jpg","ar.minshawi":"assets/reciters/minshawi-original.jpg","ar.bandarbalilah":"assets/reciters/bandarbalilah.png","ar.saudalshuraim":"assets/reciters/saudalshuraim.jpg","ar.mahermuaiqly":"assets/reciters/mahermuaiqly.png","ar.abdelazizsheim":"assets/reciters/abdelazizsheim.jpg","ar.hazzaalbalushi":"assets/reciters/hazzaalbalushi.jpg","ar.haithamaljadani":"assets/reciters/haithamaljadani.jpg","ar.raadalkurdi":"assets/reciters/raadalkurdi-v349.png","ar.abdulrahmanmossad":"assets/reciters/abdulrahmanmossad.jpg","ar.haithamaldukhain":"assets/reciters/haithamaldukhain.jpg","ar.ahmedkaseb":"assets/reciters/ahmedkaseb.jpg","ar.obaidamuafaq":"assets/reciters/obaidamuafaq.jpg","ar.siratulloraupov":"assets/reciters/siratulloraupov.jpg"};reciter.portrait=portraits[reciter.id]||reciter.portrait;}
export function reciterInfo(id){const r=RECITERS.find(r=>r.id===id);if(!r)throw Error('Неизвестный чтец');return r}

export function reciterHasSurah(id,number){const r=reciterInfo(id);return !r.availableSurahs||r.availableSurahs.includes(number)}
export function adjacentReciterSurah(id,number,delta){if(![-1,1].includes(delta))return null;for(let n=number+delta;n>=1&&n<=114;n+=delta)if(reciterHasSurah(id,n))return n;return null}

export const RECITER_GROUPS=[{id:'other',name:'Другие чтецы'},{id:'makkah',name:'Имамы Мекки'},{id:'madinah',name:'Имамы Медины'}];
export function groupedReciters(favorites=[]){const ids=normalizeReciterFavorites(favorites,RECITERS);return [...(ids.length?[{id:'favorites',name:'Избранные чтецы',reciters:ids.map(reciterInfo)}]:[]),...RECITER_GROUPS.map(group=>({...group,reciters:RECITERS.filter(r=>(r.group||'other')===group.id&&!ids.includes(r.id))}))].filter(group=>group.reciters.length);}
export function reciterOptions(selected,favorites=[],{offline=false}={}){return groupedReciters(favorites).map(group=>{const entries=group.reciters.filter(r=>!offline||r.offline!==false);return entries.length?'<optgroup label="'+group.name+'">'+entries.map(r=>'<option value="'+r.id+'" '+(selected===r.id?'selected':'')+'>'+String(r.name).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</option>').join('')+'</optgroup>':'';}).join('');}
